// ═══════════════════════════════════════════════════════════
// ADAPTFIT AI LOGOS
// ═══════════════════════════════════════════════════════════
const LOGO_MALE    = 'data:image/png;base64,';
const LOGO_FEMALE  = 'data:image/png;base64,';
const LOGO_NEUTRAL = 'data:image/png;base64,';

function updateLogos(gender) {
  const src = gender === 'female' ? LOGO_FEMALE : LOGO_MALE;
  document.querySelectorAll('.adaptfit-logo-img').forEach(el => el.src = src);
}

document.addEventListener('DOMContentLoaded', () => {
  updateLogos('male'); // default
});